function MillstoneSpindleBearingMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillstoneSpindleBearingMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillstoneSpindleBearingMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillstoneSpindleBearingMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillstoneSpindleBearingMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillstoneSpindleBearingMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillstoneSpindleBearingMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillstoneSpindleBearingMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillstoneSpindleBearingMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillstoneSpindleBearingMaker.buildings==0 then return false,"Potrebna lezajna delavnica" end; if not MillstoneSpindleBearingMaker.maker then return false,"Potreben lezajnik" end; return true end
