function MillstoneSpindleBearingMaker.completeMaking(m) local q=1.0+(MillstoneSpindleBearingMaker.getQualityBonus()/100); if MillstoneSpindleBearingMaker.maker then q=q+(MillstoneSpindleBearingMaker.maker.skill/140) end; q=math.min(2.5,q); MillstoneSpindleBearingMaker.productStock[m.productType]=(MillstoneSpindleBearingMaker.productStock[m.productType] or 0)+m.quantity; MillstoneSpindleBearingMaker.totalProducts=MillstoneSpindleBearingMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillstoneSpindleBearingMaker.maker then MillstoneSpindleBearingMaker.maker.itemsMade=MillstoneSpindleBearingMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillstoneSpindleBearingMaker.maker.skill=math.min(100,MillstoneSpindleBearingMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ležaj izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millstonespindlebearing.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
